function box(x1,y1,z1,x2,y2,z2,t){
  var a1=Math.min(x1,x2),a2=Math.max(x1,x2);
  var b1=Math.min(y1,y2),b2=Math.max(y1,y2);
  var c1=Math.min(z1,z2),c2=Math.max(z1,z2);
  for(var a=a1;a<=a2;a++)for(var b=b1;b<=b2;b++)for(var c=c1;c<=c2;c++)block(a,b,c,t);
}

function cylinder(cx,cz,radius,height,yBase,type,taper){
  taper=taper||0;
  for(var y=0;y<height;y++){
    var frac=height>1?y/(height-1):0;
    var r=Math.round(radius*(1-taper*frac));
    if(r<1)r=1;
    for(var dy=-r;dy<=r;dy++){
      for(var dz=-r;dz<=r;dz++){
        if(dy*dy+dz*dz<=radius*radius+0.5){
          block(cx+dy,yBase+y,cz+dz,type);
        }
      }
    }
  }
}

